using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using MicroEMR.Web.Models.EncounterSoapTemplates;using MicroEMR.Web.Services.EncounterSoapTemplates;
namespace MicroEMR.Web.Controllers;
[Authorize]public sealed class EncounterSoapTemplatesController:Controller{private readonly IEncounterSoapTemplateApiClient _client;public EncounterSoapTemplatesController(IEncounterSoapTemplateApiClient client)=>_client=client;
[HttpGet]public async Task<IActionResult>Index(string status="Active",CancellationToken token=default){status=status.ToLowerInvariant()switch{"inactive"=>"Inactive","all"=>"All",_=>"Active"};return View(new EncounterSoapTemplateIndexViewModel{Status=status,Templates=await _client.GetAllAsync(status,token)});}
[HttpGet]public async Task<IActionResult>Active(CancellationToken token)=>Json(await _client.GetAllAsync("Active",token));
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(SaveEncounterSoapTemplateViewModel model,CancellationToken token){if(!ModelState.IsValid)return BadRequest(new{success=false,message="Template name is required."});await _client.CreateAsync(model,token);return Json(new{success=true});}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Update(UpdateEncounterSoapTemplateViewModel model,CancellationToken token){if(!ModelState.IsValid||model.EncounterSoapTemplateUid==Guid.Empty)return BadRequest(new{success=false,message="Invalid template."});var x=await _client.UpdateAsync(model.EncounterSoapTemplateUid,model,token);return x is null?NotFound():Json(new{success=true});}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>SetActive(SetEncounterSoapTemplateActiveViewModel model,CancellationToken token){var x=await _client.SetActiveAsync(model.EncounterSoapTemplateUid,model.IsActive,token);return x is null?NotFound():Json(new{success=true});}}
